func TxCreateFor(id uint64, collectionId uint64) []byte {
	b := beginRecord(txCreateFor)
	b = binary.LittleEndian.AppendUint64(b, id)
	b = binary.LittleEndian.AppendUint64(b, collectionId)
	return endRecord(b)
}

