// TxTemplateEnd: Close the innermost template scope.
func TxTemplateEnd() []byte {
	b := beginRecord(txTemplateEnd)
	return endRecord(b)
}

// TxCollectionMove: Move an entry so it sits before the entry whose key is the one value in `before`, or to the end when `before` is empty. Keys, never indices: order is data, and indices would race the very deltas that change them.
func TxCollectionMove(collectionId uint64, path []any, key any, before []any) []byte {
	b := beginRecord(txCollectionMove)
	b = binary.LittleEndian.AppendUint64(b, collectionId)
	b = encodeValues(b, path)
	b = encodeValue(b, key)
	b = encodeValues(b, before)
	return endRecord(b)
}

// TxCollectionUpdateField: Set one field of an entry's record; only bindings on that field re-resolve. `variant` is the discriminant the guest witnessed in the match that produced this write — the scene asserts it against the entry's stored variant, so a drifted model fails loudly; it never changes a constructor (update does).
func TxCollectionUpdateField(collectionId uint64, path []any, key any, field uint32, variant uint32, value any) []byte {
	b := beginRecord(txCollectionUpdateField)
	b = binary.LittleEndian.AppendUint64(b, collectionId)
	b = encodeValues(b, path)
	b = encodeValue(b, key)
	b = binary.LittleEndian.AppendUint32(b, field)
	b = binary.LittleEndian.AppendUint32(b, variant)
	b = encodeValue(b, value)
	return endRecord(b)
}

// TxVariantCase: Inside a For over a sum: the records that follow (until the next variant_case or template_end) are the blueprint for this variant. Cases must be total at template_end; an empty case renders a constructor as nothing, explicitly.
func TxVariantCase(variant uint32) []byte {
	b := beginRecord(txVariantCase)
	b = binary.LittleEndian.AppendUint32(b, variant)
	b = binary.LittleEndian.AppendUint32(b, 0)
	return endRecord(b)
}

// TxWidgetCommand: A one-shot command aimed at a live widget: momentary, fire-and-forget, never state at rest — the app's sanctioned crossing into widget-owned state (clear, focus). The widget answers through its normal occurrence path; nothing is recorded and nothing replays on rebuild. The command enum is the closed vocabulary; each verb is admitted by a real artifact, per the escalation policy.
func TxWidgetCommand(widgetId uint64, command uint32) []byte {
	b := beginRecord(txWidgetCommand)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = binary.LittleEndian.AppendUint32(b, command)
	b = binary.LittleEndian.AppendUint32(b, 0)
	return endRecord(b)
}

// TxCreateWindow: Create an auxiliary window (capability-gated: a host without KAYA_CAP_AUX_WINDOWS rejects it at the root). Materializes hidden; mounting a root presents it. Ids are guest-allocated, below the internal bit; 0 is the primary and always exists.
func TxCreateWindow(windowId uint64) []byte {
	b := beginRecord(txCreateWindow)
	b = binary.LittleEndian.AppendUint64(b, windowId)
	return endRecord(b)
}

// TxDestroyWindow: Close and forget an auxiliary window: the native window and its views are released wholesale, and the scene forgets the mounted tree (widget ids are never reused, so stale entries are inert). The primary is not destroyable: the process owns it.
func TxDestroyWindow(windowId uint64) []byte {
	b := beginRecord(txDestroyWindow)
	b = binary.LittleEndian.AppendUint64(b, windowId)
	return endRecord(b)
}

// TxShowAlert: Request a modal alert over a live window (0 = primary): the request/result grammar's first client (DESIGN.md, Presentation contexts). One atomic record: title, message, `actions` action labels (0..=2 — the platform floor; ContentDialog's three slots are two actions plus close), and the always-present cancel slot, which is what EVERY platform-native dismissal (Esc, back, outside tap) resolves to. All five Values are Str; action slots beyond `actions` ride empty and are ignored. Alert ids are guest-chosen; one alert may be live per process, and the id retires when its result fires.
func TxShowAlert(window uint64, alert uint64, actions uint32, title any, message any, action0 any, action1 any, cancel any) []byte {
	b := beginRecord(txShowAlert)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, alert)
	b = binary.LittleEndian.AppendUint32(b, actions)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = encodeValue(b, title)
	b = encodeValue(b, message)
	b = encodeValue(b, action0)
	b = encodeValue(b, action1)
	b = encodeValue(b, cancel)
	return endRecord(b)
}

// TxPushEntry: Push a navigation entry onto `window`'s stack (0 = the primary surface; no capability gate — every host materializes a serial stack natively). Entry ids share the surface namespace with windows: one guest-side allocator, and mount's target field addresses either. Materializes covered/incoming; mounting a root into it presents it. The covered root below stays alive — retained until popped (DESIGN.md, Navigation).
func TxPushEntry(window uint64, entry uint64) []byte {
	b := beginRecord(txPushEntry)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, entry)
	return endRecord(b)
}

// TxPopEntry: Pop the top navigation entry from `window`'s stack and forget its mounted tree, exactly as destroy_window does (ids are never reused, so stale targets fail loudly). Popping an empty stack is a scene error. Multi-pop is binding sugar: N of these in one transaction, animated by backends as the NET stack change per batch.
func TxPopEntry(window uint64) []byte {
	b := beginRecord(txPopEntry)
	b = binary.LittleEndian.AppendUint64(b, window)
	return endRecord(b)
}

// TxSetEntryProp: Bind a navigation-entry property (ENTRY_PROPS). Same tail convention as SET_PROPERTY_NOTE, except SOURCE_ELEMENT is rejected — entries are not collection elements.
func TxSetEntryProp(entry uint64, prop uint32, source uint32) []byte {
	b := beginRecord(txSetEntryProp)
	b = binary.LittleEndian.AppendUint64(b, entry)
	b = binary.LittleEndian.AppendUint32(b, prop)
	b = binary.LittleEndian.AppendUint32(b, source)
	return endRecord(b)
}

// TxAddSection: Append a section to `window`'s section set (0 = the primary surface; no capability gate — every platform has a sections idiom). Section ids share the surface namespace with windows and entries: one guest-side allocator, and mount's target field addresses any of them. The first section added becomes the selected one; the set is APPEND-ONLY — this grammar has no destruction verbs by design, and every section's root is retained while covered (DESIGN.md, Sections).
func TxAddSection(window uint64, section uint64) []byte {
	b := beginRecord(txAddSection)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, section)
	return endRecord(b)
}

// TxSelectSection: Select a section programmatically: configuration, not a user act — it never echoes section_selected (the echo doctrine). The section must already be added to `window`; switching is SELECTION, not lifecycle — the covered root stays alive.
func TxSelectSection(window uint64, section uint64) []byte {
	b := beginRecord(txSelectSection)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, section)
	return endRecord(b)
}

// TxSetSectionProp: Bind a section property (SECTION_PROPS). Same tail convention as SET_PROPERTY_NOTE, except SOURCE_ELEMENT is rejected — sections are not collection elements.
func TxSetSectionProp(section uint64, prop uint32, source uint32) []byte {
	b := beginRecord(txSetSectionProp)
	b = binary.LittleEndian.AppendUint64(b, section)
	b = binary.LittleEndian.AppendUint32(b, prop)
	b = binary.LittleEndian.AppendUint32(b, source)
	return endRecord(b)
}

// TxMenuItemCreate: Create a menu item of `kind` (menu_kind) in the menu-item id space — its own guest allocator (c_menu_item), distinct from every widget, node, and surface space. Items are live, append-only, and never removed in v1 (DESIGN.md, Menus).
func TxMenuItemCreate(item uint64, kind uint32) []byte {
	b := beginRecord(txMenuItemCreate)
	b = binary.LittleEndian.AppendUint64(b, item)
	b = binary.LittleEndian.AppendUint32(b, kind)
	b = binary.LittleEndian.AppendUint32(b, 0)
	return endRecord(b)
}

// TxMenuItemAppend: Append `child` under grouping node `parent`. Single-parent: an item acquires exactly one parent or anchor and ids are never reused. The closed parent/child grammar (menu accepts menu/radio_group/action/toggle/separator; radio_group accepts only radio_option; leaves accept nothing) and the depth cap are validated at the root.
func TxMenuItemAppend(parent uint64, child uint64) []byte {
	b := beginRecord(txMenuItemAppend)
	b = binary.LittleEndian.AppendUint64(b, parent)
	b = binary.LittleEndian.AppendUint64(b, child)
	return endRecord(b)
}

// TxMenubarAppend: Append a top-level grouping node (menu or radio_group) to `window`'s command catalog — the window anchor, riding the window construct under the window-attribute unification rule (0 = the primary surface). The bar accepts only grouping nodes; duplicate shortcuts within the window's catalog are a root error.
func TxMenubarAppend(window uint64, item uint64) []byte {
	b := beginRecord(txMenubarAppend)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, item)
	return endRecord(b)
}

// TxContextAttach: Attach a context catalog rooted at `item` to a live widget — the same command vocabulary scoped to a noun. The editable text controls (entry, textarea) reject attachment (their native edit menus are dress), a context root cannot be a radio_option, and a shortcut anywhere in the subtree is a root error (shortcuts need a window catalog home).
func TxContextAttach(widget uint64, item uint64) []byte {
	b := beginRecord(txContextAttach)
	b = binary.LittleEndian.AppendUint64(b, widget)
	b = binary.LittleEndian.AppendUint64(b, item)
	return endRecord(b)
}

// TxContextAttachNode: Attach a context catalog to a template node (the Tpl zone): every stamped copy shows the same catalog, and an activation carries that copy's key path — the keys ARE the noun (the on_click_node encoding). Same rejections as context_attach.
func TxContextAttachNode(node uint64, item uint64) []byte {
	b := beginRecord(txContextAttachNode)
	b = binary.LittleEndian.AppendUint64(b, node)
	b = binary.LittleEndian.AppendUint64(b, item)
	return endRecord(b)
}

// TxSetMenuProp: Bind a menu property (MENU_PROPS). Same tail convention as SET_PROPERTY_NOTE, except SOURCE_ELEMENT is rejected — menu items are not collection elements — and icon/primary/ shortcut reject SOURCE_SIGNAL (const-only). label and enabled fan out through the signal-write path; the domain of a signal-bound value is validated on the COMPLETE coalesced value at the transaction barrier.
func TxSetMenuProp(item uint64, prop uint32, source uint32) []byte {
	b := beginRecord(txSetMenuProp)
	b = binary.LittleEndian.AppendUint64(b, item)
	b = binary.LittleEndian.AppendUint32(b, prop)
	b = binary.LittleEndian.AppendUint32(b, source)
	return endRecord(b)
}

// TxShowFileDialog: Request the platform's file picker over a live window (0 = primary), on the alert's request/result grammar (DESIGN.md, File dialogs). Dialog ids are guest-chosen; one dialog may be live per process, and the id retires when its result fires. `multiple` is 0 or 1 — every backend supports both, spelled four ways (a flag on SwiftUI and AppKit, a different METHOD on GTK and WinUI, a different CONTRACT on Android). `filters` is advisory and rides as alternating Str values, a label then its space-separated extensions: every platform treats them as a default view rather than a guarantee, so the guest still validates what it got.
func TxShowFileDialog(window uint64, dialog uint64, multiple uint32, filters []any) []byte {
	b := beginRecord(txShowFileDialog)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, dialog)
	b = binary.LittleEndian.AppendUint32(b, multiple)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = encodeValues(b, filters)
	return endRecord(b)
}

// TxCopy: Put one clip on the system clipboard, offered in several REPRESENTATIONS at once (DESIGN.md, Clipboard; docs/clipboard-plan.md). A clip is not a string: every platform models it as one item available in several types, and the consumer takes the richest it understands — so an app offers html AND text, and pasting into Pages keeps the formatting while a plain field still works. A RECORD RATHER THAN A LIST, which is what makes at-most-one-per-kind structural instead of a runtime duplicate check. `present` is a mask over the `clip` enum for the single-valued kinds; the two plural ones carry counts. `reps` holds the populated ones in the CANONICAL ORDER, which kaya fixes once because richness is a property of the kind rather than of the app's intent, and the wire's preference order (macOS type order, X11 TARGETS) has to be right whoever wrote the guest. THE ORDER IS DESCENDING CLIP VALUE, which is descending richness, so a backend writes what it is handed in the order it is handed: `custom_count` pairs of Str id and I64 blob, `file_count` I64 handles, I64 image blob, Str html, Str text. Files are the SAME CAPABILITY the picker returns — a handle redeemed with kaya_open_picked — so copying a file and picking one are one currency and the bytes never move through kaya.
func TxCopy(present uint32, fileCount uint32, customCount uint32, reps []any) []byte {
	b := beginRecord(txCopy)
	b = binary.LittleEndian.AppendUint32(b, present)
	b = binary.LittleEndian.AppendUint32(b, fileCount)
	b = binary.LittleEndian.AppendUint32(b, customCount)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = encodeValues(b, reps)
	return endRecord(b)
}

// TxReadClipboard: Read the clipboard OUTSIDE any paste gesture, on the alert's request/result grammar. `accepting` is an ACCEPT LIST, the same space-separated Str the widget prop carries: the closed kinds by name plus any custom ids, which are open and so could never be a mask. The answer carries the first match by canonical richness, so exactly one representation is ever materialised. THIS IS THE PRIVILEGED ONE, and it is named for what it is rather than for pasting. A user's paste arrives at the widget's hook and costs nothing; this asks without a gesture, which the platforms have deliberately made expensive — iOS 16 PROMPTS when the content came from another app, and the read blocks until the user answers (measured); Android returns nothing unless the app has focus; Wayland delivers no offer to an unfocused client. Reaching for a thing called paste in an editor would have cost a permission prompt for content the hook delivers free, which is why this name is not that one. An empty answer covers denied, absent, and nothing-we-accept alike.
func TxReadClipboard(request uint64, accepting any) []byte {
	b := beginRecord(txReadClipboard)
	b = binary.LittleEndian.AppendUint64(b, request)
	b = encodeValue(b, accepting)
	return endRecord(b)
}

// TxUndoGroup: Mark this transaction as ONE undoable step in `window`'s ledger, under `label` (a non-empty Str, validated at the root like every other authored grammar). MUST BE THE FIRST RECORD OF THE BATCH and may appear once: a transaction is a bare list with no header, so per-transaction metadata has nowhere else to live, and head-of-batch is the one position that cannot be ambiguous (docs/undo-plan.md D2). A WIRE FACT AND NOT A BINDING CONVENTION, so both interpreters and check-verbs see it and a binding that forgets to emit it fails a byte-compared scene instead of grouping wrong in silence.  THE UNDOABLE SET IS THE REACTIVE HALF (D4): a marked batch may hold signal writes and the five collection deltas, whose inverse the core derives from state it already keeps. PURE EFFECTS — focus today, scroll when it lands — are permitted and simply not restored (A2): undo restores state, not where you were looking. Anything else (const prop sets, create/destroy/mount, window/nav/section/menu structure, clear, commands, dialog and clipboard requests) is REFUSED at apply, loudly, naming the op — an app that wants a widget property undoable binds it to a signal, which is the reactive doctrine saying what it already said. A refused group leaves the scene exactly as it was.  The window is explicit because the core cannot derive it: a signal write names no surface, and the scene keeps no widget-to-window map. 0 is the primary.
func TxUndoGroup(window uint64, label any) []byte {
	b := beginRecord(txUndoGroup)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = encodeValue(b, label)
	return endRecord(b)
}

// TxHighlightRanges: DECLARE the set of decorated ranges on a textarea, replacing whatever was declared before (docs/ranges-plan.md D1/D2). `ranges` holds 2*`count` I64 values — start then end, in UTF-8 BYTE offsets into the widget's current guest-visible text; an empty set is the clear.  THE OFFSET UNIT AND ITS THREE RULES, once, here, because four of the five platforms answer a malformed offset differently and one of them ABORTS THE PROCESS (docs/ranges-units.md §3: an out-of-range NSTextStorage attribute is an NSRangeException, exit 134). The core refuses before lowering: `start <= end`, `end <= text.len()`, and both endpoints on a CODE-POINT boundary. A GRAPHEME split is deliberately NOT refused and is the stated carve-out — the platforms disagree about what a grapheme is (java.text.BreakIterator counts the ZWJ family as 11 clusters where .NET and Swift count 5, measured), so a core that refused by its own table would refuse ranges three platforms honor. The range covers exactly the code points it names; a platform may widen what it PAINTS to the whole cluster.  APP-OWNED AND NEVER TRACKED. kaya adjusts nothing across edits: a declared set is bound to the text it was declared against, and a backend paints it only while the widget still holds that text — the first keystroke, programmatic write or native undo drops the set with nothing said. The app re-declares from the fold `text_changed` already drives, which is the same uncontrolled contract the text itself has. Range tracking is editor-component work and lives in the app.  TEXTAREA ONLY this milestone. The entry is deferred with measured per-platform reasons (docs/deferred.md): GTK's entry highlight rides absolute byte offsets that do not follow edits and is not readable over AT-SPI, macOS destroys an entry's highlight the moment it loses focus (the field editor is the window's, not the field's), and no consumer wants it — an editor's find bar decorates a document.
func TxHighlightRanges(widgetId uint64, count uint32, ranges []any) []byte {
	b := beginRecord(txHighlightRanges)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = binary.LittleEndian.AppendUint32(b, count)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = encodeValues(b, ranges)
	return endRecord(b)
}

// TxSelectRange: Put the textarea's SELECTION at one range (UTF-8 byte offsets, validated exactly as highlight_ranges is). `start == end` is a caret and is legal — every platform's text object models a degenerate range.  ITS OWN RECORD RATHER THAN A `widget_command`, which it otherwise is exactly (momentary, fire-and-forget, the app's sanctioned crossing into widget-owned state): that record's layout has nowhere to put offsets, and growing it two U64s would hang two dead fields on `clear` and `focus` and make `focus(w, 0, 0)` representable.  REFUSED DURING AN INPUT-METHOD COMPOSITION, in every backend, under the reason `ime_composition` (docs/ranges-plan.md D4). Measured on macOS: honoring it COMMITS the marked text into the document and into the app's model mid-word, which is data loss shaped like a feature, and it shifts every later offset by the committed length. A refusal here is a NO-OP AND NOT A PANIC — unlike undo's D4, which refuses an app-programming error the app can fix. Composition state is on no kaya channel and never will be (there are no widget mirror reads), so the same app code is correct one millisecond and refused the next; the app that wants the selection waits for the composition to end, which `text_changed` announces anyway. HIGHLIGHT and REVEAL do not disturb a composition and are not refused (measured, same probe).
func TxSelectRange(widgetId uint64, start uint64, stop uint64) []byte {
	b := beginRecord(txSelectRange)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = binary.LittleEndian.AppendUint64(b, start)
	b = binary.LittleEndian.AppendUint64(b, stop)
	return endRecord(b)
}

// TxRevealRange: Scroll the textarea so a range is inside the viewport (UTF-8 byte offsets, validated exactly as highlight_ranges is). A PURE EFFECT: it moves no state, the selection is untouched, and per docs/undo-plan.md A2 undo does not restore it — undo restores state, not where you were looking, which is why it is permitted inside an undo group and simply not inverted.  WHAT `inside the viewport` MEANS IS THE PLATFORM'S, not kaya's: each backend calls its own scroll-to-range (scrollRangeToVisible, ScrollIntoView, gtk_text_view_scroll_to_iter, bringIntoView), so how much context lands around the range is native behaviour. The observable kaya fixes is containment, which is the only thing every platform agrees on.
func TxRevealRange(widgetId uint64, start uint64, stop uint64) []byte {
	b := beginRecord(txRevealRange)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = binary.LittleEndian.AppendUint64(b, start)
	b = binary.LittleEndian.AppendUint64(b, stop)
	return endRecord(b)
}

// TxShowSaveDialog: Request the platform's save dialog over a live window (0 = primary), on the SAME request/result grammar as the open picker (docs/save-plan.md D2): guest-chosen dialog ids out of the one id space, one dialog live per process whichever kind it is, and the answer arriving as a file_dialog_result whose id retires there. `filters` is the picker's advisory encoding unchanged — alternating Str values, a label then its space-separated extensions. `suggested_name` is the name the dialog opens with, which every platform takes (nameFieldStringValue, GtkFileDialog's initial name, IFileSaveDialog's SetFileName, EXTRA_TITLE, the export controller's filename) and none guarantees: the user renames it, and Android may append an extension matching the mime type, so a guest reads the name it GOT rather than the name it asked for.  THE ANSWER IS EXACTLY ONE LOCATOR OR NONE, and there is no `multiple` twin of the picker's flag: no platform's save dialog names two destinations. Cancel is the empty answer, the picker's rule verbatim.  WHAT THE DESTINATION IS FOR is the decision with the semantics in it (docs/save-plan.md D1): the result's handle opens with CREATE, so opening a name the dialog invented succeeds and yields an EMPTY file on every platform. Android and iOS hand back a document that already exists; macOS, GTK and Windows hand back a name for a file nobody has made (measured: macOS does not even truncate on Replace). The core absorbs that, not the guest, and NOT a fourth file mode — creation is a property of the destination the dialog promised, never of the caller's intent, and a mode would let a guest ask for it on a file it merely opened.
func TxShowSaveDialog(window uint64, dialog uint64, suggestedName any, filters []any) []byte {
	b := beginRecord(txShowSaveDialog)
	b = binary.LittleEndian.AppendUint64(b, window)
	b = binary.LittleEndian.AppendUint64(b, dialog)
	b = encodeValue(b, suggestedName)
	b = encodeValues(b, filters)
	return endRecord(b)
}

// TxSetBrandAccent: REQUEST the app's brand accent (docs/styling-plan.md D1/D2). `seed` is one packed sRGB (0xRRGGBB) — the only value most apps write; `mask` says which per-appearance overrides are present (bit 0 = light, bit 1 = dark) and `light`/`dark` carry them when set, 0 otherwise. Per-PLATFORM values never ride the wire: the binding resolves its platform at runtime and sends one resolved trio (values may vary per platform; code and wire shape never do).  A REQUEST, uniformly: a platform may let its user override the app's accent — macOS does today (an app accent applies only while the system accent is multicolor), and the semantics does not change if another platform grows the preference. The app states a brand; the platform stays the judge of its chrome.  SET ONCE, before the first mount: the root refuses a second write and a late one — brand is identity, not state, and a slot that could flip at runtime would promise a theme- switching surface the vocabulary deliberately does not have.  The app NEVER writes a foreground and NEVER writes contrast variants; the core derives fill/on-fill/standalone and a hover/pressed ramp per appearance (the danger-band clamp, docs/styling-plan.md D1) and hands every backend VALUES. Backends do not re-derive — except Compose, which receives the SEED as well because Material 3's own documented flow derives a full role scheme from it, and kaya defers to the platform's derivation where one exists.
func TxSetBrandAccent(seed uint32, mask uint32, light uint32, dark uint32) []byte {
	b := beginRecord(txSetBrandAccent)
	b = binary.LittleEndian.AppendUint32(b, seed)
	b = binary.LittleEndian.AppendUint32(b, mask)
	b = binary.LittleEndian.AppendUint32(b, light)
	b = binary.LittleEndian.AppendUint32(b, dark)
	return endRecord(b)
}

// TxSetBrandTypeface: REQUEST the app's brand typeface (docs/styling-plan.md D6, Slice 2b). `family` is the default family name every platform falls back to; `platforms` carries the optional per-platform overrides as PAIRS — an I64 platform tag from the `platform` enum, then that platform's family as a Str — and `mask` bit 0 says a `font` BLOB is present (an empty Str rides in its slot when it is not).  THE FAMILY, NEVER THE SCALE (ratified DESIGN.md): sizes, weights, metrics and the whole type ramp stay the platform's. Substituting a family into the platform's own ramp is what makes the swap safe, and it is the role tier — not a font size — that carries emphasis.  PER-PLATFORM VALUES RIDE THE WIRE, unlike the accent's, and the asymmetry is the design (Slice 2b): a BINDING cannot know its platform — the JVM says "Linux" on Android — but a LOWERING is its platform, so each backend picks its own row out of `platforms` and no platform id is ever needed on the guest side. A colour resolves to one number a binding can compute anywhere; a family name has to survive to the backend that will look it up.  FONT BYTES RIDE THE BLOB CHANNEL, register-then-resolve: when `font` carries bytes the backend hands them to its platform's app-font API (CTFontManager, fontconfig, the Compose/DWrite routes), reads back the family name the registration produced, and the NAME machinery takes over unchanged — one resolution, one observation, one fallback for both forms. A registered blob's own family wins over `family` on the backend that registered it.  SET ONCE, before the first mount — the accent's wall verbatim, and for its reason: a typeface that could flip at runtime would promise the theme-switching surface the vocabulary deliberately does not have.  THE RISK IS THE SILENT FALLBACK. Every platform's font API renders SOMETHING for a family it does not have, so a typo is invisible to every other observation: each backend gates on the family being PRESENT and otherwise leaves the platform default in place, and `expect_typeface` reads the RESOLVED family off the real views rather than echoing the request.
func TxSetBrandTypeface(mask uint32, family any, platforms []any, font any) []byte {
	b := beginRecord(txSetBrandTypeface)
	b = binary.LittleEndian.AppendUint32(b, mask)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = encodeValue(b, family)
	b = encodeValues(b, platforms)
	b = encodeValue(b, font)
	return endRecord(b)
}

// TxSetAppIdentity: DECLARE the app's identity — the name it goes by and the picture that stands for it (docs/app-identity-plan.md, ratified 2026-08-18). `name` is a Str; `mask` bit 0 says an `icon` BLOB is present, and an empty Str rides its slot when it is not — the typeface's mask-plus-always-written-slot convention, copied rather than reinvented, so the two records decode the same way and one mask/slot disagreement test covers the shape.  A TRANSACTION VERB AND NOT A WINDOW PROP, because identity is per-APP where WINDOW_PROPS is per-window. `title` already lives there and is the WINDOW's title; the identity name is a different thing and the vocabulary must not conflate them (on Windows the two meet in one string, and it is the backend's single caption writer that composes them, never two authors).  ONE PICTURE, FIVE ROUTES. The same PNG reaches the macOS Dock, the Windows taskbar/alt-tab and caption, an X11 window's _NET_WM_ICON, the Android launcher and the iOS Home Screen — each by its platform's own route, some at runtime off these bytes and some at build time off the same file in the tree. One PNG goes in and each lowering converts (NSImage(data:), BitmapImage.SetSource, an HICON, a GdkTexture); no .ico, no .icns, no per-platform artwork on the wire.  THE FOUR WALLS ARE THE BRAND'S, VERBATIM, and for the brand's reasons. SET ONCE: a second write dies in the root, in every language at once. BEFORE THE FIRST MOUNT: so no backend shows an unidentified frame it must repaint. EMPTY IS REFUSED: an app that wants the platform's own identity declares none at all, and an empty string would sail through five lowerings indistinguishable from a default. NOT UNDOABLE: identity is not state.  THE BYTES ARE NOT INSPECTED IN THE CORE — the typeface's rule transfers exactly. Whether a blob is an image is a question only the platform's own decoder can answer, and a guess that disagreed with the decoder would be worse than no answer. Each backend decodes, and the observation reports what the DECODER produced (a size, sampled pixels) rather than echoing the request, so bytes that are not an image fail exactly like an icon that never applied.
func TxSetAppIdentity(mask uint32, name any, icon any) []byte {
	b := beginRecord(txSetAppIdentity)
	b = binary.LittleEndian.AppendUint32(b, mask)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = encodeValue(b, name)
	b = encodeValue(b, icon)
	return endRecord(b)
}

// TxSetColumnHeaders: DECLARE the column header bar on a For's container, replacing whatever was declared before (docs/tables-plan.md). `titles` holds `count` Str values, one per column in visual order; `sorted` is the 0-based index of the column showing the sort indicator, or u32::MAX for none (alert_choice's cancel-sentinel precedent); `direction` is 0 ascending, 1 descending, read only when `sorted` names a column.  ONE RECORD FOR THE WHOLE BAR, titles and indicator together, because the header's state is one declaration: a sort flip re-sends a handful of short strings and buys atomicity — no window where new titles show a stale indicator. A dedicated record and not a prop because a prop carries ONE Value and titles are many, with spaces (`accepts`' space-separated trick is out); the carrier is highlight_ranges' count-plus-Values shape.  THE TARGET IS THE FOR'S CONTAINER — there is no List widget; a For materializes as a Column and this record is what turns that container into a table where the size class and the platform have the idiom (DESIGN.md's column-props ruling). The root refuses a target that is not a For container, a `count` of 0, an empty title, a `sorted` outside 0..count that is not the sentinel, and a `direction` past 1.  PATH ADDRESSING (dynamic tables, docs/tables-plan.md): the Values carry `path_len` KEY values FIRST, then the `count` titles — sort_requested's identity convention pointed the other way. path_len 0 with a live For's container id is the flat case above; path_len 0 with a nested For's TEMPLATE NODE id declares the bar for EVERY copy (stored on the site, applied at each stamp); path_len > 0 with the template node id and keys outermost-first re-declares ONE stamped copy's bar — the per-copy sort indicator. A keyed target that names no stamped copy is refused loudly.  ROWS MUST FIT THE COLUMNS: with N columns declared, every stamped row's template root must be a Row with exactly N children, checked at stamp time in the core so every backend inherits the wall — a mismatched template dies naming the row and both counts instead of rendering N-1 cells under N headers on some platforms and not others.  THE INDICATOR IS THE GUEST'S: a header click emits sort_requested and changes nothing; the guest reorders its collection by key and re-declares this record with the new indicator. Configuration, not an occurrence source — the echo doctrine. Not undoable: the header bar is not state, and the order underneath it already rides collection_move's undo run.
func TxSetColumnHeaders(widgetId uint64, sorted uint32, direction uint32, count uint32, pathLen uint32, titles []any) []byte {
	b := beginRecord(txSetColumnHeaders)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = binary.LittleEndian.AppendUint32(b, sorted)
	b = binary.LittleEndian.AppendUint32(b, direction)
	b = binary.LittleEndian.AppendUint32(b, count)
	b = binary.LittleEndian.AppendUint32(b, pathLen)
	b = encodeValues(b, titles)
	return endRecord(b)
}

// TxSetDrawing: DECLARE the whole drawing on a canvas widget, replacing whatever was declared before (docs/canvas-plan.md §3.1). `ops` holds `path_len` KEY values FIRST, then `count` op values — set_column_headers' convention verbatim, and what lets a canvas live inside a For row template: path_len 0 with a live widget id is the flat case, path_len 0 with a template node id declares the drawing for every stamped copy, path_len > 0 re-declares one copy's.  THE OP STREAM IS A FLAT RUN OF TAGGED VALUES: an i64 `draw_op` opcode followed by its operands (§3.3). `vb_w`/`vb_h` are the VIEWBOX — the coordinate system the guest draws in AND the canvas's natural size in device-independent points — which is what keeps one op stream identical on five platforms (§3.2, invariant 6).  ONE RECORD FOR THE WHOLE DRAWING, never a patch, on set_column_headers' reasoning: a half-updated chart is the same defect as new titles under a stale indicator. NOT UNDOABLE: a drawing renders app state, it is not state.  THE CORE RASTERIZES AND THE BACKEND BLITS (ruling 1). No backend interprets an op, so every refusal in §3.5 happens in the only place that draws.
func TxSetDrawing(widgetId uint64, vbW any, vbH any, count uint32, pathLen uint32, ops []any) []byte {
	b := beginRecord(txSetDrawing)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = encodeValue(b, vbW)
	b = encodeValue(b, vbH)
	b = binary.LittleEndian.AppendUint32(b, count)
	b = binary.LittleEndian.AppendUint32(b, pathLen)
	b = encodeValues(b, ops)
	return endRecord(b)
}

// TxSetSizePolicy: WHAT THIS CANVAS DOES WITH A TRACK THAT IS NOT ITS VIEWBOX (`size_policy`; docs/canvas-plan.md §3.2.1). A drawing is a FUNCTION OF SIZE and `redraw`/`tick` say so: the core hands the canvas the size it was assigned, through draw_requested/tick, and rasterizes what comes back at that size. `scale` and `fixed` DECLARE THE FUNCTION CONSTANT, which is what lets the core answer a size change by itself — `scale` re-rasterizes the held display list under a UNIFORM FIT with a letterbox, `fixed` never adapts at all.  NOT SENT FOR `scale`: it is the default a guest that declares nothing gets. THE GUEST NEVER SPELLS THIS NUMBER — the binding lowers `fixed` (the one true property) and the presence of an on_draw/on_tick handler; a canvas with no policy record is `scale`.  LIVE CANVASES ONLY in this slice: a template node is refused by name (docs/deferred.md's template-zone size policy entry).
func TxSetSizePolicy(widgetId uint64, policy uint32) []byte {
	b := beginRecord(txSetSizePolicy)
	b = binary.LittleEndian.AppendUint64(b, widgetId)
	b = binary.LittleEndian.AppendUint32(b, policy)
	b = binary.LittleEndian.AppendUint32(b, 0)
	return endRecord(b)
}

