// ClipValues is one representation as the decoder hands it over:
// the clip kind, and its values with blobs already redeemed to
// bytes. The sum itself is the hand-written tier's — this is the
// taste-free shape the wire carries.
//
// Kind is a SINGLE member of the clip enum and never a mask (you
// offer many and you receive one); 0 with no values is the
// universal empty answer.
type ClipValues struct {
	Kind   uint32
	Values []any
}

// parseClip decodes a representation at `at`: the clip kind, then
// its Values block. Blobs are redeemed and RELEASED here.
func parseClip(rec []byte, at int) (ClipValues, int) {
	clip := ClipValues{Kind: binary.LittleEndian.Uint32(rec[at:])}
	count := int(binary.LittleEndian.Uint32(rec[at+8:]))
	at += 16
	for i := 0; i < count; i++ {
		vtype := binary.LittleEndian.Uint32(rec[at:])
		vlen := int(binary.LittleEndian.Uint32(rec[at+4:]))
		body := rec[at+8 : at+8+vlen]
		switch vtype {
		case ValueI64:
			clip.Values = append(clip.Values, int64(binary.LittleEndian.Uint64(body)))
		case ValueBlob:
			clip.Values = append(clip.Values, occurrenceBlob(binary.LittleEndian.Uint64(body)))
		default:
			clip.Values = append(clip.Values, string(body))
		}
		at += 8 + (vlen+7)&^7
	}
	return clip, at
}

// parseValue decodes one wire value at `at` and returns the offset
// after it. Blobs are redeemed and RELEASED here, as parseClip does:
// an occurrence blob is a table handle nothing else retires.
func parseValue(rec []byte, at int) (any, int) {
	vtype := binary.LittleEndian.Uint32(rec[at:])
	vlen := int(binary.LittleEndian.Uint32(rec[at+4:]))
	body := rec[at+8 : at+8+vlen]
	var v any
	switch vtype {
	case ValueBool:
		v = body[0] != 0
	case ValueI64:
		v = int64(binary.LittleEndian.Uint64(body))
	case ValueF64:
		v = math.Float64frombits(binary.LittleEndian.Uint64(body))
	case ValueBlob:
		v = occurrenceBlob(binary.LittleEndian.Uint64(body))
	default:
		v = string(body)
	}
	return v, at + 8 + (vlen+7)&^7
}

// ParseOccurrence decodes one occurrence record (header included).
// keys is nil when id is a widget id; otherwise id is a template
// node id and keys is the copy's key path, outermost first. payload
// is the entry's new text (string) for occTextChanged, the
// checkbox's new state (bool) for occToggled, the slider's new
// value (float64) for occValueChanged, nil for clicks. ok is
// false for pad/unknown records.
func ParseOccurrence(rec []byte) (kind uint16, id uint64, keys []any, payload any, ok bool) {
	kind = binary.LittleEndian.Uint16(rec[4:])
	if kind != occButtonClicked && kind != occTextChanged && kind != occToggled && kind != occValueChanged && kind != occCloseRequested && kind != occWindowClosed && kind != occAlertResult && kind != occEntryPopped && kind != occBackRequested && kind != occSectionSelected && kind != occMenuActivated && kind != occMenuToggled && kind != occMenuValueChanged && kind != occFileDialogResult && kind != occClipboardResult && kind != occPasted && kind != occUndone && kind != occRedone && kind != occSortRequested && kind != occDrawRequested && kind != occTick {
		return 0, 0, nil, nil, false
	}
	id = binary.LittleEndian.Uint64(rec[8:])
	if kind == occAlertResult {
		// The alert's one answer: id + u32 choice (AlertChoice*).
		return kind, id, nil, binary.LittleEndian.Uint32(rec[16:]), true
	}
	if kind == occFileDialogResult {
		// The picker's answer: id, a count, then three Values
		// per file (handle, name, local_path). EMPTY IS CANCEL.
		count := int(binary.LittleEndian.Uint32(rec[16:]))
		at := 32 // past id, count, pad, values count, reserved
		files := make([]PickedFile, 0, count)
		for i := 0; i < count; i++ {
			vals := [3]any{}
			for j := 0; j < 3; j++ {
				vtype := binary.LittleEndian.Uint32(rec[at:])
				vlen := int(binary.LittleEndian.Uint32(rec[at+4:]))
				body := rec[at+8 : at+8+vlen]
				if vtype == ValueI64 {
					vals[j] = int64(binary.LittleEndian.Uint64(body))
				} else {
					vals[j] = string(body)
				}
				at += 8 + (vlen+7)&^7
			}
			handle, _ := vals[0].(int64)
			name, _ := vals[1].(string)
			localPath, _ := vals[2].(string)
			files = append(files, PickedFile{
				Handle: uint64(handle), Name: name, LocalPath: localPath})
		}
		return kind, id, nil, files, true
	}
	if kind == occClipboardResult {
		clip, _ := parseClip(rec, 16)
		return kind, id, nil, clip, true
	}
	if kind == occUndone || kind == occRedone {
		// The window is the id; then the four run LENGTHS, the
		// group's label (EMPTY for a typing episode), and one
		// flat values tail the runs cut up in order.
		signals := int(binary.LittleEndian.Uint32(rec[16:]))
		texts := int(binary.LittleEndian.Uint32(rec[20:]))
		entries := int(binary.LittleEndian.Uint32(rec[24:]))
		orders := int(binary.LittleEndian.Uint32(rec[28:]))
		at := 32
		label, at := parseValue(rec, at)
		count := int(binary.LittleEndian.Uint32(rec[at:]))
		at += 8 // count, reserved
		flat := make([]any, count)
		for i := range flat {
			flat[i], at = parseValue(rec, at)
		}
		read := 0
		next := func(n int) []any {
			if read+n > len(flat) {
				panic("kaya: an undo delta is truncated")
			}
			out := flat[read : read+n]
			read += n
			return out
		}
		num := func(v any) int64 {
			n, isInt := v.(int64)
			if !isInt {
				panic("kaya: an undo delta wanted an integer")
			}
			return n
		}
		var delta UndoDelta
		for i := 0; i < signals; i++ {
			pair := next(2)
			delta.Signals = append(delta.Signals,
				UndoSignal{Signal: uint64(num(pair[0])), Value: pair[1]})
		}
		for i := 0; i < texts; i++ {
			head := next(3)
			size := int(num(head[0]))
			pathLen := int(num(head[2]))
			body := next(size - 3)
			text, _ := body[pathLen].(string)
			delta.Texts = append(delta.Texts, UndoText{
				ID:   uint64(num(head[1])),
				Path: append([]any(nil), body[:pathLen]...),
				Text: text,
			})
		}
		for i := 0; i < entries; i++ {
			// size, collection, flags (bit 0 = the entry EXISTS),
			// variant, path_len — then the path, the key, and the
			// record's fields. size counts itself.
			head := next(5)
			size := int(num(head[0]))
			pathLen := int(num(head[4]))
			body := next(size - 5)
			entry := UndoEntry{
				Collection: uint64(num(head[1])),
				Path:       append([]any(nil), body[:pathLen]...),
				Key:        body[pathLen],
				Present:    num(head[2]) != 0,
				Variant:    uint32(num(head[3])),
			}
			if entry.Present {
				entry.Record = append([]any(nil), body[pathLen+1:]...)
			}
			delta.Entries = append(delta.Entries, entry)
		}
		for i := 0; i < orders; i++ {
			head := next(3)
			size := int(num(head[0]))
			pathLen := int(num(head[2]))
			body := next(size - 3)
			delta.Orders = append(delta.Orders, UndoOrder{
				Collection: uint64(num(head[1])),
				Path:       append([]any(nil), body[:pathLen]...),
				Keys:       append([]any(nil), body[pathLen:]...),
			})
		}
		if read != len(flat) {
			panic("kaya: an undo delta has trailing values")
		}
		name, _ := label.(string)
		return kind, id, nil, undoReport{label: name, delta: delta}, true
	}
	if kind == occCloseRequested || kind == occWindowClosed || kind == occEntryPopped || kind == occBackRequested {
		// Surface lifecycle records carry the surface id alone —
		// no key path, no payload (derived from the record shapes).
		return kind, id, nil, nil, true
	}
	if kind == occSectionSelected {
		// Surface-pair records (window, section): the SECOND id
		// keys the handler; the first rides as the payload.
		return kind, binary.LittleEndian.Uint64(rec[16:]), nil, id, true
	}
	pathLen := binary.LittleEndian.Uint32(rec[16:])
	at := 24
	for i := uint32(0); i < pathLen; i++ {
		vtype := binary.LittleEndian.Uint32(rec[at:])
		vlen := int(binary.LittleEndian.Uint32(rec[at+4:]))
		payload := rec[at+8 : at+8+vlen]
		switch vtype {
		case ValueBool:
			keys = append(keys, payload[0] != 0)
		case ValueI64:
			keys = append(keys, int64(binary.LittleEndian.Uint64(payload)))
		case ValueF64:
			keys = append(keys, math.Float64frombits(binary.LittleEndian.Uint64(payload)))
		default:
			keys = append(keys, string(payload))
		}
		at += 8 + (vlen+7)&^7
	}
	if kind == occSortRequested {
		payload = binary.LittleEndian.Uint32(rec[20:])
	}
	if kind == occTextChanged || kind == occToggled || kind == occValueChanged || kind == occMenuToggled || kind == occMenuValueChanged {
		vtype := binary.LittleEndian.Uint32(rec[at:])
		vlen := int(binary.LittleEndian.Uint32(rec[at+4:]))
		switch vtype {
		case ValueBool:
			payload = rec[at+8] != 0
		case ValueI64:
			payload = int64(binary.LittleEndian.Uint64(rec[at+8:]))
		case ValueF64:
			payload = math.Float64frombits(binary.LittleEndian.Uint64(rec[at+8:]))
		default:
			payload = string(rec[at+8 : at+8+vlen])
		}
	}
	if kind == occPasted {
		clip, _ := parseClip(rec, at)
		payload = clip
	}
	if kind == occDrawRequested || kind == occTick {
		// The canvas asks carry a run of BARE values after the key
		// path — the assigned size, and a tick's frame time — with
		// no count in front, so they are read until the record ends
		// (docs/canvas-plan.md §3.2.1).
		end := int(binary.LittleEndian.Uint32(rec[0:]))
		tail := []any{}
		for at < end {
			var v any
			v, at = parseValue(rec, at)
			tail = append(tail, v)
		}
		payload = tail
	}
	return kind, id, keys, payload, true
}
